def main():
    path = ROOT / 'content/catalog.json'
    data = json.loads(path.read_text())
    for card in data['cards']:
        if card['id'] not in DESCRIPTIONS: continue
        body = card['body']
        before, tail = body.split('## Описание\n\n', 1)
        _, after = tail.split('\n\n## ', 1)
        paragraphs = DESCRIPTIONS[card['id']]
        card['summary'] = paragraphs[0]
        card['body'] = before + '## Описание\n\n' + '\n\n'.join(paragraphs) + '\n\n## ' + after
        # Consistent labels; numeric values and all model scopes remain intact.
        article, notes = card['body'].split('\n\n## Служебные сведения', 1)
        article = article.replace('| Категория |', '| Класс |').replace('| Корпус |', '| Материал корпуса |')
        article = article.replace('| Наполнение |', '| Тип ВВ |').replace('| Масса наполнения |', '| Масса ВВ |')
        article = article.replace('| Взрывчатое наполнение — NEQ', '| Масса ВВ — NEQ')
        article = article.replace('| Окраски, перечисленные ESAG |', '| Варианты окраски |')
        article = article.replace('| Окраска, описанная в источнике |', '| Окраска описанного образца |')
        article = article.replace('| Масса, г | 20 400 |', '| Полная масса | 20 400 г (20,4 кг) |')
        article = article.replace('| Размеры, мм | 250 (диаметр), 440 (высота на подставке) |', '| Габариты | 250 мм (диаметр), 440 мм (высота на подставке) |')
        card['body'] = article + '\n\n## Служебные сведения' + notes
    assert len(DESCRIPTIONS) == 20
    data['contentVersion'] = 150
    data['catalogVersion'] = 150
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
    print('Rewritten:', len(DESCRIPTIONS), 'cards; catalog 150')

if __name__ == '__main__': main()
